columbus_crew_players_info = players.WHERE(
    players.team_join.Name == "Columbus Crew"
).CALCULATE(
    Player=players.Player,
    Years_Played=players.Years_Played
)

result = wrestler.eliminations.WHERE(
    INT(wrestler.days_held) > 50
).CALCULATE(
    Time=time
)

result = cities.WHERE(
    (cities.temperatures.feb > cities.temperatures.jun) | (HAS(cities.hosting_cities) == 1)
).CALCULATE(
    city_name=city
)

products_never_ordered_count = product.WHERE(
    HASNOT(order_items) == 1
).CALCULATE(
    number_of_products_never_ordered=COUNT(product)
)

